"""A small web server on Python's standard library: NoClick runs it in a container, on the port it names."""

import json
import os
from http.server import BaseHTTPRequestHandler, HTTPServer


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/api/hello":
            body, kind = json.dumps({{"hello": "world"}}).encode(), "application/json"
        else:
            body, kind = b"<h1>{name}</h1><p>Edit main.py, then run noclick deploy.</p>", "text/html"
        self.send_response(200)
        self.send_header("Content-Type", kind)
        self.end_headers()
        self.wfile.write(body)


if __name__ == "__main__":
    HTTPServer(("0.0.0.0", int(os.environ.get("PORT", "8080"))), Handler).serve_forever()
